import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideBell,
  lucideCrosshair,
  lucideLayoutDashboard,
  lucideMoon,
  lucideRadar,
  lucideSearch,
  lucideSettings,
  lucideShieldAlert,
  lucideSun,
  lucideUserPlus,
  lucideUsers,
} from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmInputImports } from '@spartan-ng/helm/input';
import { HlmSidebarImports } from '@spartan-ng/helm/sidebar';
import { HlmTooltipImports } from '@spartan-ng/helm/tooltip';
import { AppViewModel } from './app.view-model';

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmAvatarImports,
    HlmButtonImports,
    HlmInputImports,
    HlmSidebarImports,
    HlmTooltipImports,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideBell,
      lucideCrosshair,
      lucideLayoutDashboard,
      lucideMoon,
      lucideRadar,
      lucideSearch,
      lucideSettings,
      lucideShieldAlert,
      lucideSun,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
}
